#define _GNU_SOURCE
#include <dlfcn.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <netinet/tcp.h>
#include <errno.h>
#include <unistd.h>
static void enable(int fd) {
  const int yes=1;
  if (setsockopt(fd, IPPROTO_TCP, TCP_NODELAY, &yes, sizeof(yes))!=0) _exit(90);
}
int accept4(int fd, struct sockaddr *address, socklen_t *length, int flags) {
  int (*real_accept)(int,struct sockaddr*,socklen_t*,int)=dlsym(RTLD_NEXT,"accept4");
  int result=real_accept(fd,address,length,flags);int saved=errno;
  if(result>=0)enable(result);
  errno=saved;return result;
}
int connect(int fd, const struct sockaddr *address, socklen_t length) {
  int (*real_connect)(int,const struct sockaddr*,socklen_t)=dlsym(RTLD_NEXT,"connect");
  if(address->sa_family==AF_INET && ntohs(((const struct sockaddr_in*)address)->sin_port)==19090)enable(fd);
  return real_connect(fd,address,length);
}

