from pathlib import Path
import sys
p=Path(sys.argv[1])/'libs/server-core/src/service/RoomService.cpp'
s=p.read_text();s=s.replace('#include <optional>','#include <algorithm>\n#include <chrono>\n#include <cstdio>\n#include <vector>\n#include <optional>')
probe=r'''
// 임시 진단 전용: 잠금 전후 시각을 스레드별 메모리에 저장하고 종료 시 출력한다.
struct LockSample { const char* operation; long long wait_ns; long long hold_ns; };
struct LockSamples {
  std::vector<LockSample> values;
  std::size_t dropped = 0;
  LockSamples() { values.reserve(100000); }
  ~LockSamples() {
    for (const auto& s : values) {
      std::fprintf(stderr, "{\"event\":\"room_mutex_sample\",\"operation\":\"%s\",\"wait_ns\":%lld,\"hold_ns\":%lld}\n", s.operation, s.wait_ns, s.hold_ns);
    }
    std::fprintf(stderr, "{\"event\":\"room_mutex_end\",\"dropped\":%zu}\n", dropped);
  }
};
thread_local LockSamples lock_samples;
class MeasuredLock {
 public:
  MeasuredLock(std::mutex& mutex, const char* operation)
      : samples_(lock_samples), mutex_(mutex), operation_(operation) {
    before_ = Clock::now();
    mutex_.lock();
    acquired_ = Clock::now();
  }
  ~MeasuredLock() {
    const auto released = Clock::now();
    mutex_.unlock();
    if (samples_.values.size() < samples_.values.capacity()) {
      samples_.values.push_back({operation_,
          std::chrono::duration_cast<std::chrono::nanoseconds>(acquired_-before_).count(),
          std::chrono::duration_cast<std::chrono::nanoseconds>(released-acquired_).count()});
    } else { ++samples_.dropped; }
  }
 private:
  using Clock = std::chrono::steady_clock;
  LockSamples& samples_;
  std::mutex& mutex_;
  const char* operation_;
  Clock::time_point before_, acquired_;
};
'''
s=s.replace('namespace {\n','namespace {\n'+probe,1).replace('std::lock_guard<std::mutex> lock(mutex_);','MeasuredLock lock(mutex_, __func__);')
p.write_text(s)

