import struct,json,re,sys,pathlib,collections,urllib.parse,math
root=pathlib.Path(sys.argv[1]); flows={}; requests={}; responses=[]; packets=[]; anomalies=collections.Counter()
pattern=re.compile(r'run=(\d+);sender=(\d+);seq=(\d+);sent_us=(\d+);')
with (root/'traffic.pcap').open('rb') as f:
 assert f.read(24)[:4]==b'\xd4\xc3\xb2\xa1'
 while True:
  h=f.read(16)
  if not h:break
  sec,usec,n,orig=struct.unpack('<IIII',h);frame=f.read(n)
  if len(frame)!=n:raise RuntimeError('truncated capture')
  if frame[12:14]!=b'\x08\x00':continue
  ip=frame[14:];ih=(ip[0]&15)*4
  if ip[9]!=6:continue
  tcp=ip[ih:];sport,dport,seq,ack=struct.unpack('!HHII',tcp[:12]);th=(tcp[12]>>4)*4;flags=tcp[13];payload=tcp[th:struct.unpack('!H',ip[2:4])[0]-ih];us=sec*1000000+usec
  packets.append({'unix_us':us,'source_port':sport,'destination_port':dport,'seq':seq,'ack':ack,'flags':flags,'bytes':len(payload)})
  key=(sport,dport)
  if flags&2:flows[key]={'next':seq+1,'buffer':b''}
  if not payload:continue
  if key not in flows:anomalies['missing_syn']+=1;continue
  flow=flows[key]
  if seq<flow['next']:
   overlap=flow['next']-seq;anomalies['overlap_segments']+=1
   payload=payload[overlap:];seq+=overlap
  if seq!=flow['next']:anomalies['gap_segments']+=1;continue
  flow['next']+=len(payload);flow['buffer']+=payload
  while len(flow['buffer'])>=4:
   size,typ=struct.unpack('!HH',flow['buffer'][:4])
   if not 4<=size<=65535:raise RuntimeError('invalid frame size')
   if len(flow['buffer'])<size:break
   data=flow['buffer'][4:size].decode('utf-8');flow['buffer']=flow['buffer'][size:]
   match=pattern.search(urllib.parse.unquote(data))
   if not match:continue
   identity=tuple(map(int,match.groups()));item={'id':identity,'unix_us':us,'source_port':sport,'destination_port':dport}
   if typ==20:
    if identity in requests:anomalies['duplicate_request']+=1
    requests[identity]=item
   elif typ==22:responses.append(item)

def stats(values):
 values=sorted(values)
 if not values:return {'count':0}
 return {'count':len(values),'p50_us':values[math.ceil(len(values)*.5)-1],'p95_us':values[math.ceil(len(values)*.95)-1],'p99_us':values[math.ceil(len(values)*.99)-1],'max_us':values[-1]}
groups=collections.defaultdict(list);byid=collections.defaultdict(list);examples=[]
for response in responses:
 identity=response['id']
 if identity not in requests:anomalies['missing_request']+=1;continue
 delta=response['unix_us']-requests[identity]['unix_us'];groups[identity[0]].append(delta);byid[identity].append(delta)
 if 35000<delta<50000 and len(examples)<20:examples.append({'request':requests[identity],'response':response,'wire_delay_us':delta})
summary={'requests':len(requests),'responses':len(responses),'anomalies':dict(anomalies),'request_to_response_wire':{k:stats(v) for k,v in groups.items()},'request_to_first_response_wire':{run:stats([min(v) for k,v in byid.items() if k[0]==run]) for run in groups},'response_fanout_counts':dict(collections.Counter(map(len,byid.values()))),'examples':examples}
if examples:
 x=examples[0];port=x['response']['destination_port'];lo=x['request']['unix_us']-55000;hi=x['response']['unix_us']+1000
 summary['example_connection_packets']=[p for p in packets if port in (p['source_port'],p['destination_port']) and lo<=p['unix_us']<=hi]
(root/'latency-packets.json').write_text(json.dumps(summary,ensure_ascii=False,indent=2)+'\n');print(json.dumps({k:v for k,v in summary.items() if k not in ['examples','example_connection_packets']},indent=2))
